class Counter:
    def __init__(self):
        self.value = 0

    def inc(self):
        self.value += 1

c = Counter()
c.inc()
c.inc()
print(c.value)

class Dog:
    def __init__(self, name, age):
        self.name, self.age = name, age
    def __str__(self):
        return f"Dog {self.name}, {self.age} yrs"
    def __repr__(self):
        return f"Dog({self.name!r}, {self.age})"

d = Dog("Sharik", 3)
print(d)
print(repr(d))

class Account:
    def __init__(self):
        self._balance = 0
    def deposit(self, amount):
        if amount <= 0:
            raise ValueError("amount must be positive")
        self._balance += amount
    def balance(self):
        return self._balance

a = Account()
a.deposit(100)
print(a.balance())
a.deposit(-5)

class Dog:
    def __init__(self, name, age):
        self.name, self.age = name, age

dogs = [Dog("Rex", 5), Dog("Bim", 2), Dog("Lucky", 8)]
print([d.name for d in dogs if d.age > 3])

def get_age(d):
    return d.age

print([d.name for d in sorted(dogs, key=get_age)])

class Stack:
    def __init__(self):
        self._items = []
    def push(self, x):
        self._items.append(x)
    def pop(self):
        return self._items.pop()
    def is_empty(self):
        return not self._items

s = Stack()
s.push(1)
s.push(2)
print(s.pop(), s.is_empty())
